const PTS=[[1.6,1.6],[2.3,1.8],[1.9,2.4],[7.7,1.7],[8.4,1.9],[8.0,2.4],[1.7,4.7],[2.4,5.0],[2.0,5.4],[7.6,4.8],[8.3,5.1],[8.0,5.5]];
const SX=x=>60+x*52, SY=y=>480-y*52;
const ROLE=['input','output'];
const NAME=['A','B'];
function d2(p,c){const dx=p[0]-c[0],dy=p[1]-c[1];return dx*dx+dy*dy;}
function freshC(c0){const c=[c0[0].slice(),c0[1].slice()];return {start:[c0[0].slice(),c0[1].slice()],c:c,trail:[[c[0].slice()],[c[1].slice()]],a:null,rounds:0,done:false,msg:'Press Assign: each point joins its nearest centroid.'};}
function fresh(inp){return freshC([[inp.c1x,inp.c1y],[inp.c2x,inp.c2y]]);}
function sep(a,b,minD,half){const dx=b[0]-a[0],dy=b[1]-a[1];const d=Math.hypot(dx,dy);if(d>=minD)return [a,b,false];let ux=1,uy=0;if(d>1e-6){ux=dx/d;uy=dy/d;}const mx=(a[0]+b[0])/2,my=(a[1]+b[1])/2;return [[mx-ux*half,my-uy*half],[mx+ux*half,my+uy*half],true];}
export function initialState({inputs}){return fresh(inputs);}
export function reduce({state,event,inputs}){
 const s=state;
 if(event.type==='input'){const inp=Object.assign({},inputs);inp[event.input]=event.value;return fresh(inp);}
 if(event.type==='drag_start'||event.type==='drag_move'||event.type==='drag_end'){
  const k=event.target==='c0'?0:event.target==='c1'?1:-1;
  if(k<0||typeof event.x!=='number'||typeof event.y!=='number')return s;
  const x=Math.round(sdk.clamp((event.x-60)/52,0,10)*10)/10;
  const y=Math.round(sdk.clamp((480-event.y)/52,0,7)*10)/10;
  const st=[s.start[0].slice(),s.start[1].slice()];st[k]=[x,y];
  const n=freshC(st);
  n.msg='Start '+NAME[k]+' moved. Press Assign to begin.';
  return n;
 }
 if(event.type!=='action')return s;
 if(event.action==='reset')return freshC(s.start||[[inputs.c1x,inputs.c1y],[inputs.c2x,inputs.c2y]]);
 if(event.action==='assign'){
  const a=PTS.map(p=>d2(p,s.c[0])<=d2(p,s.c[1])?0:1);
  const same=s.a&&a.every((v,i)=>v===s.a[i]);
  const n=s.a?a.filter((v,i)=>v!==s.a[i]).length:a.length;
  if(same)return Object.assign({},s,{done:true,msg:'No point changed group: converged.'});
  return Object.assign({},s,{a:a,done:false,msg:(s.a?n+' point(s) switched group.':'Every point is coloured by its nearest centroid.')+' Now press Update.'});
 }
 if(event.action==='update'){
  if(!s.a)return Object.assign({},s,{msg:'Press Assign first: no points belong to a centroid yet.'});
  const c=[0,1].map(k=>{let sx=0,sy=0,n=0;PTS.forEach((p,i)=>{if(s.a[i]===k){sx+=p[0];sy+=p[1];n++;}});return n?[sx/n,sy/n]:s.c[k].slice();});
  const moved=c.some((q,k)=>Math.abs(q[0]-s.c[k][0])+Math.abs(q[1]-s.c[k][1])>1e-9);
  if(!moved)return Object.assign({},s,{done:true,msg:'Centroids did not move: converged.'});
  const trail=[s.trail[0].concat([c[0]]).slice(-12),s.trail[1].concat([c[1]]).slice(-12)];
  return Object.assign({},s,{c:c,trail:trail,rounds:s.rounds+1,done:false,msg:'Each centroid moved to the average of its points. Press Assign again.'});
 }
 return s;
}
export function evaluate({inputs,state}){
 const s=state||fresh(inputs);
 const o=[];
 o.push(sdk.box('plot',40,90,560,410,{role:'neutral',opacity:0.15}));
 o.push(sdk.text('ttl',40,40,'12 points in 4 clumps, 2 centroids (A, B)'));
 o.push(sdk.text('ax',320,525,'x from 0 to 10, y from 0 to 7 (same scale)',{align:'middle'}));
 const C=sep([SX(s.c[0][0]),SY(s.c[0][1])],[SX(s.c[1][0]),SY(s.c[1][1])],36,19);
 const S0=sep([SX(s.trail[0][0][0]),SY(s.trail[0][0][1])],[SX(s.trail[1][0][0]),SY(s.trail[1][0][1])],20,11);
 let sse=0;
 PTS.forEach((p,i)=>{const k=s.a?s.a[i]:(d2(p,s.c[0])<=d2(p,s.c[1])?0:1);sse+=d2(p,s.c[k]);
  if(s.a)o.push(sdk.line('ln'+i,SX(p[0]),SY(p[1]),C[k][0],C[k][1],{role:ROLE[k],opacity:0.25}));});
 PTS.forEach((p,i)=>{o.push(sdk.circle('p'+i,SX(p[0]),SY(p[1]),14,{role:s.a?ROLE[s.a[i]]:'neutral'}));});
 [0,1].forEach(k=>{const tr=s.trail[k];
  if(tr.length>1)o.push(sdk.polyline('tr'+k,tr.map(q=>[SX(q[0]),SY(q[1])]),{role:ROLE[k],opacity:0.6}));
  o.push(sdk.circle('st'+k,S0[k][0],S0[k][1],18,{role:ROLE[k],opacity:0.3}));});
 [0,1].forEach(k=>{o.push(sdk.circle('c'+k,C[k][0],C[k][1],34,{text:NAME[k],role:ROLE[k]}));});
 if(C[2])o.push(sdk.text('ovl',40,70,'A and B are at (almost) the same spot, drawn side by side; ties go to A.',{role:'warning'}));
 const X=640;
 o.push(sdk.text('h1',X,110,'Centroid A: ('+sdk.format(s.c[0][0],2)+', '+sdk.format(s.c[0][1],2)+')',{role:'input'}));
 o.push(sdk.text('h2',X,140,'Centroid B: ('+sdk.format(s.c[1][0],2)+', '+sdk.format(s.c[1][1],2)+')',{role:'output'}));
 o.push(sdk.text('h3',X,180,'Updates done: '+s.rounds));
 o.push(sdk.text('h4',X,215,(s.a?'Total squared distance to own centroid:':'Total squared distance to nearest centroid:')));
 o.push(sdk.text('h5',X,245,sdk.format(sse,2),{role:'prediction'}));
 o.push(sdk.math('h6',X,285,'\\sum_i \\lVert x_i - c_{g(i)} \\rVert^2'));
 const words=s.msg.split(' ');let line='',ln=[];words.forEach(w=>{if((line+' '+w).length>36){ln.push(line);line=w;}else line=line?line+' '+w:w;});ln.push(line);
 ln.slice(0,4).forEach((t,j)=>o.push(sdk.text('m'+j,X,335+j*26,t,{role:s.done?'success':'neutral'})));
 o.push(sdk.text('k1',X,460,'Drag A or B to set a new start.'));
 o.push(sdk.text('k2',X,488,'Try left/right starts, then top/bottom.'));
 return {frame:{width:960,height:540,objects:o,readouts:[{id:'sse',value:sse},{id:'rounds',value:s.rounds}]},quantities:{sse:sse,rounds:s.rounds,converged:s.done?1:0}};
}

